namespace backend.Tests.Validators;

// Shared across CreateLocationCommandValidatorTests and UpdateLocationCommandValidatorTests
// (#1724) — both validators run BoundaryGeoJson through the same LocationBoundaryParser rules,
// so their boundary-case fixtures were byte-identical duplicates before this extraction.
internal static class BoundaryGeoJsonFixtures
{
    internal static string BuildPolygonWithVertexCount(int vertexCount)
    {
        var sb = new System.Text.StringBuilder();
        sb.Append("""{"type":"Polygon","coordinates":[[""");
        for (var i = 0; i < vertexCount; i++)
        {
            // First/last point closes the ring at [0,0]; everything in between alternates [1,0]
            // and [0,0] — the shape doesn't need to be valid/simple, since the vertex-count check
            // runs (and fails) before LocationBoundaryParser ever checks IsSimple/IsValid.
            var x = i == 0 || i == vertexCount - 1 ? 0 : i % 2;
            sb.Append('[').Append(x).Append(",0]");
            if (i < vertexCount - 1) sb.Append(',');
        }
        sb.Append("]]}");
        return sb.ToString();
    }

